arguments.command:
set -e
[ ! -e packages/cli ]
[ -z "$(git ls-files 'packages/cli/**')" ]
node <<'NODE'
const fs=require('fs');
const p=JSON.parse(fs.readFileSync('package.json','utf8'));
if ('agentos' in (p.scripts||{})) throw new Error('root agentos script remains');
if ((p.scripts?.build||'').includes('@agentos/cli')) throw new Error('CLI build remains');
const l=JSON.parse(fs.readFileSync('package-lock.json','utf8'));
for (const k of Object.keys(l.packages||{})) if (k==='packages/cli'||k==='node_modules/@agentos/cli') throw new Error(`lock entry remains: ${k}`);
NODE
if git grep -n -I -E 'agentos[[:space:]]+help|packages/cli/dist' -- ':!.chain/**'; then exit 1; fi
echo 'structural acceptance=PASS'

content.text:
      "path": "scripts/os-isolation/rollback.sh",
